# artlibrary.py: Coloring Book (39 pictures), Rainbow Letters, Calm Bubbles and 6 new sing-alongs in Art & Music.
import base64, hashlib, os, sys
FULL = {'app/src/playzone/artContent.ts': ('', 'f21fd6625b0bcec44d354f0d39fcd231'), 'app/src/playzone/ArtMusic.tsx': ('', 'd201176eea3a754010ece58478296180'), 'app/src/playzone/coloringPages.ts': ('', None), 'app/src/playzone/ColoringBook.tsx': ('', None), 'app/src/playzone/RainbowLetters.tsx': ('', None), 'app/src/playzone/rainbowContent.ts': ('', None), 'app/src/playzone/CalmBubbles.tsx': ('', None), 'app/e2e/art-library.spec.ts': ('', None)}
for p, (b, orig) in FULL.items():
    if orig is None:
        if os.path.exists(p): sys.exit(p + ' already exists; not applying')
    elif hashlib.md5(open(p, 'rb').read()).hexdigest() != orig:
        sys.exit(p + ' changed since staging; not applying')
for p, (b, _) in FULL.items():
    open(p, 'wb').write(base64.b64decode(b)); print('wrote', p)
